import{a as e,c as t,i as n,l as r,n as i,o as a,r as o,s,t as c,u as l}from"./index-BPMNew2F.js";var u={class:`about`},d={class:`back`},f=c({__name:`AboutView`,setup(c){return(c,f)=>(t(),n(`main`,u,[o(`article`,null,[f[1]||=e(`<header class="head" data-v-0fefa970><h1 data-v-0fefa970>关于这个检索</h1><p class="lead" data-v-0fefa970> 一个基于<strong data-v-0fefa970>阮一峰《科技爱好者周刊》</strong>的语义搜索工具。 把每一期「工具」「资源」板块里散落的几十条链接汇总到一个搜索框里，用自然语言描述需求即可定位往期推荐。 </p></header><section data-v-0fefa970><h2 data-v-0fefa970>怎么用</h2><p data-v-0fefa970> 在搜索框输入你想做的事，比如「图片压缩」「终端配色」「OCR 识别」，回车即可。 后端把 query 通过 embedding 模型编成向量，与库内所有工具的向量算余弦相似度，按分数排序后用三层阈值收敛展示。 </p></section><section data-v-0fefa970><h2 data-v-0fefa970>技术栈</h2><ul data-v-0fefa970><li data-v-0fefa970><strong data-v-0fefa970>前端：</strong>Vue 3 + Vite，无 UI 框架；结果区用 CSS <code data-v-0fefa970>column-count</code> 实现瀑布流</li><li data-v-0fefa970><strong data-v-0fefa970>后端：</strong>Flask 开发环境 + Gunicorn 生产环境（部署在 Render Web Service，免费实例）</li><li data-v-0fefa970><strong data-v-0fefa970>Embedding：</strong>阿里云 DashScope 远程 API（<code data-v-0fefa970>qwen3.7-text-embedding</code>，768 维）；查询与库向量使用同一模型保证向量空间一致</li><li data-v-0fefa970><strong data-v-0fefa970>向量存储：</strong>开发环境读本地 <code data-v-0fefa970>vectors.jsonl</code>；生产环境走 Qdrant Cloud 余弦距离检索</li><li data-v-0fefa970><strong data-v-0fefa970>数据源：</strong><a href="https://github.com/ruanyf/weekly" target="_blank" rel="noopener" data-v-0fefa970>github.com/ruanyf/weekly</a>，每期 <code data-v-0fefa970>issue-N.md</code> 中的「工具」章节</li></ul></section><section data-v-0fefa970><h2 data-v-0fefa970>数据更新流程</h2><p data-v-0fefa970>冷启动（一次性）：本地跑抽取脚本读全部 <code data-v-0fefa970>issue-*.md</code>，批量调 DashScope 生成向量，写出 <code data-v-0fefa970>vectors.jsonl</code>，再用 <code data-v-0fefa970>--recreate</code> 全量灌入 Qdrant。</p><p data-v-0fefa970>周增量：每周新一期发布后，只针对单个文件跑抽取脚本（自动命名为 <code data-v-0fefa970>vectors_N.jsonl</code>），再增量 upsert 到 Qdrant——既有向量不动，新点按确定性 ID 去重。</p></section><section data-v-0fefa970><h2 data-v-0fefa970>字段说明</h2><p data-v-0fefa970>每张卡片顶部是工具标题（无外链时仅显示标题），右侧是该期发刊日期；描述区支持内联 Markdown 图片与链接；底部是来源 issue 文件名（链向阮一峰 GitHub 仓库）与相似度 score。卡片整体按相关度收敛展示，top 项最相关。</p></section>`,5),o(`p`,d,[s(l(i),{to:`/`},{default:r(()=>[...f[0]||=[a(`← 回到搜索`,-1)]]),_:1})])])]))}},[[`__scopeId`,`data-v-0fefa970`]]);export{f as default};